#!/usr/bin/env python3
"""ISKRA — запуск приложения на своём компьютере.

Запуск:  python iskra.py            (откроется браузер с ISKRA)
         python iskra.py --port 9000 (другой порт)
Остановка: Ctrl+C в окне, где запущен скрипт.

Нужен только Python 3.8+, без установки пакетов. Внутри файла — собранный сайт.
Демо («Посмотреть без регистрации») работает без интернета; вход по почте,
общая лента, чат и музыка из интернета — только когда есть интернет.
"""
import argparse
import base64
import gzip
import http.server
import socketserver
import threading
import webbrowser

FILES = {
    'index.html': ('text/html; charset=utf-8', ''),
    'manifest.webmanifest': ('application/manifest+json', ''),
    'favicon.svg': ('image/svg+xml', ''),
    'icon-192.png': ('image/png', ''),
    'icon-512.png': ('image/png', ''),
    'apple-touch-icon.png': ('image/png', ''),
    'sw.js': ('text/javascript; charset=utf-8', ''),
}


class Handler(http.server.BaseHTTPRequestHandler):
    def do_GET(self):
        name = self.path.split('?', 1)[0].lstrip('/') or 'index.html'
        if name not in FILES:
            name = 'index.html'
        ctype, packed = FILES[name]
        data = gzip.decompress(base64.b64decode(packed))
        self.send_response(200)
        self.send_header('Content-Type', ctype)
        self.send_header('Content-Length', str(len(data)))
        self.send_header('Cache-Control', 'no-cache')
        self.end_headers()
        self.wfile.write(data)

    def log_message(self, *args):
        pass


def main():
    parser = argparse.ArgumentParser(description='Запустить ISKRA локально')
    parser.add_argument('--port', type=int, default=8000)
    parser.add_argument('--no-browser', action='store_true', help='не открывать браузер')
    args = parser.parse_args()
    socketserver.TCPServer.allow_reuse_address = True
    with socketserver.ThreadingTCPServer(('127.0.0.1', args.port), Handler) as server:
        url = f'http://localhost:{args.port}/'
        print(f'ISKRA запущена: {url}  (остановить — Ctrl+C)')
        if not args.no_browser:
            threading.Timer(0.5, webbrowser.open, [url]).start()
        try:
            server.serve_forever()
        except KeyboardInterrupt:
            print('\nОстановлено.')


if __name__ == '__main__':
    main()
